def level2_router(llm, email):
    label = llm(f'Classify as refund, complaint or query: {email}')
    return {'refund': 'refund_queue', 'complaint': 'escalations'}.get(label, 'faq_bot')

def level3_agent(llm, tools, goal, max_steps=8):
    history = [goal]
    for _ in range(max_steps):
        decision = llm(history)                      # model chooses the next action
        if decision['action'] == 'finish':
            return decision['answer']
        result = tools[decision['action']](**decision['args'])
        history.append(result)                       # feedback shapes the next choice
    return 'stopped: step limit reached'

def run_agent(goal, call_model, tools, max_steps=10):
    messages = [{'role': 'user', 'content': goal}]          # perceive: initial state
    for step in range(max_steps):
        decision = call_model(messages)                    # reason
        if decision['type'] == 'final':
            return decision['content']
        name, args = decision['tool'], decision['args']
        try:
            result = tools[name](**args)                   # act
        except Exception as exc:
            result = f'error: {exc}'
        messages.append({'role': 'assistant', 'content': f'call {name} {args}'})
        messages.append({'role': 'tool', 'content': str(result)})  # observe
    return 'Stopped: step limit reached without a final answer.'

